def resolve(path, cwd, links):
    if links is None:
        links = {}

    link_count = 0
    max_links = 8

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
            i += 1
            continue

        # Append the component
        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        # Check if it's a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            # Parse the remaining components after this one
            remaining = components[i + 1:]

            # Parse the target
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative to the directory containing the link
                if next_path == '/':
                    link_dir = '/'
                else:
                    link_dir = next_path.rsplit('/', 1)[0]
                current = link_dir
                target_components = target.split('/')

            # Replace components with target components + remaining
            components = target_components + remaining
            i = 0
            continue

        # Not a symlink, update current
        current = next_path
        i += 1

    # Return current path, with no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

